       currentSessionID = session.id\n64:           await callHook(\"session-start\", {\n65:             session_id: session.id,\n66:           })\n67:           break\n68:         }\n69: \n70:         case \"message.updated\": {\n71:           const msg = (event as any).properties?.info\n72:           if (!msg) break\n73:           // Store message metadata (role, time, tokens, etc.)\n74:           messageStore.set(msg.id, msg)\n75:           // Track model from assistant messages\n76:           if (msg.role === \"assistant\" \u0026\u0026 msg.modelID) {\n77:             currentModel = msg.modelID\n78:           }\n79:           break\n80:         }\n81: \n82:         case \"message.part.updated\": {\n83:           const part = (event as any).properties?.part\n84:           if (!part?.messageID) break\n85: \n86:           // Fire turn-start on the first text part of a new user message\n87:           const msg = messageStore.get(part.messageID)\n88:           if (msg?.role === \"user\" \u0026\u0026 part.type === \"text\" \u0026\u0026 !seenUserMessages.has(msg.id)) {\n89:             seenUserMessages.add(msg.id)\n90:             const sessionID = msg.sessionID ?? currentSessionID\n91:             if (sessionID) {\n92:               await callHook(\"turn-start\", {\n93:                 session_id: sessionID,\n94:                 prompt: part.text ?? \"\",\n95:                 model: currentModel ?? \"\",\n96:               })\n97:             }\n98:           }\n99:           break\n100:         }\n101: \n102:         case \"session.status\": {\n103:           // session.status fires in both TUI and non-interactive (run) mode.\n104:           // session.idle is deprecated and not reliably emitted in run mode.\n105:           const props = (event as any).properties\n106:           if (props?.status?.type !== \"idle\") break\n107:           const sessionID = props?.sessionID ?? currentSessionID\n108:           if (!sessionID) break\n109:           // Use sync variant: `opencode run` exits on the same idle event,\n110:           // so an async hook would be killed before completing.\n111:           callHookSync(\"turn-end\", {\n112:             session_id: sessionID,\n113:             model: currentModel ?? \"\",\n114:           })\n115:           break\n116:         }\n117: \n118:         case \"session.compacted\": {\n119:           const sessionID = (event as any).properties?.sessionID\n120:           if (!sessionID) break\n121:           await callHook(\"compaction\", {\n122:             session_id: sessionID,\n123:           })\n124:           break\n125:         }\n126: \n127:         case \"session.deleted\": {\n128:           const session = (event as any).properties?.info\n129:           if (!session?.id) break\n130:           seenUserMessages.clear()\n131:           messageStore.clear()\n132:           currentSessionID = null\n133:           // Use sync variant: session-end may fire during shutdown.\n134:           callHookSync(\"session-end\", {\n135:             session_id: session.id,\n136:           })\n137:           break\n138:         }\n139: \n140:         case \"server.instance.disposed\": {\n141:           // Fires when OpenCode shuts down (TUI close or `opencode run` exit).\n142:           // session.deleted only fires on explicit user deletion, not on quit,\n143:           // so this is the only reliable way to end sessions on exit.\n144:           if (!currentSessionID) break\n145:           const sessionID = currentSessionID\n146:           seenUserMessages.clear()\n147:           messageStore.clear()\n148:           currentSessionID = null\n149:           // Use sync variant: this is the last event before process exit.\n150:           callHookSync(\"session-end\", {\n151:             session_id: sessionID,\n152:           })\n153:           break\n154:         }\n155:       }\n156:     },\n157:   }\n158: }\n\n(End of file - total 158 lines)\n\u003c/content\u003e","status":"success"},"type":"tool_use"}]}
